-- Admin-managed FAQs for app (Android/iOS) and website — General, Service-based, RSA
CREATE TABLE IF NOT EXISTS public.public_faqs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  faq_group VARCHAR(20) NOT NULL CHECK (faq_group IN ('GENERAL', 'SERVICE', 'RSA')),
  section_key VARCHAR(80) NOT NULL DEFAULT 'general',
  section_title VARCHAR(120) NOT NULL DEFAULT 'General',
  question TEXT NOT NULL,
  answer TEXT NOT NULL,
  display_order INT NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  visible_app BOOLEAN NOT NULL DEFAULT TRUE,
  visible_web BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_public_faqs_group_section_order
  ON public.public_faqs (faq_group, section_key, display_order, created_at);

COMMENT ON TABLE public.public_faqs IS 'Unified FAQs for home, service pages, RSA screen, website /faq, and RSA landing';

