INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'What is My FNG?', 'My FNG - Friendly Neighbourhood Garage is a network of over 100+ A Grade Multi-brand Car Servicing and Repair Stations across Mumbai, Navi Mumbai, Thane, Palghar, Nashik and Pune. We connect car owners to A-grade service centers to ensure hassle-free and high-quality maintenance experiences.', 1, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='What is My FNG?');
INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'What brands of cars do you service at My FNG?', 'My FNG services all major car brands. Our skilled technicians are trained to handle a wide range of vehicle makes and models ensuring comprehensive care for your car.', 2, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='What brands of cars do you service at My FNG?');
