INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'What services does My FNG Offer?', 'My FNG offers a wide range of car services including routine maintenance, oil changes, brake repairs, engine diagnostics, tyre services and complex repairs. Our service centers are equipped to handle all your car servicing needs.', 4, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='What services does My FNG Offer?');
INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'How can I book a service appointment with My FNG?', 'You can book service via MyFNG AI Booking Agent - https://myfng.in/ai-booking or online through our website www.myfng.in/book-service or by calling our customer support. We offer flexible scheduling to accommodate your convenience.', 5, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='How can I book a service appointment with My FNG?');
