INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'How Can I Contact You For More Questions?', 'If you have any additional questions or need assistance you can reach out to us via our website www.myfng.in/contact-us or call us at +91-9152307030. Our customer support team is here to help.', 9, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='How Can I Contact You For More Questions?');
