INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'Can Periodic Car Service Improve My Car''s Fuel Efficiency?', 'Yes, regular servicing can enhance your car''s fuel efficiency by ensuring all systems are functioning optimally. This includes replacing filters, maintaining proper tire pressure and keeping the engine well-tuned.', 11, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='Can Periodic Car Service Improve My Car''s Fuel Efficiency?');
INSERT INTO public.public_faqs (faq_group, section_key, section_title, question, answer, display_order, active, visible_app, visible_web) SELECT 'GENERAL', 'general', 'General Car Service', 'How Long Will The Car Service Take?', 'The time required for a periodic service depends on the work needed and your car''s condition. On average a standard service may take between 5 to 6 hours. We will provide you with an estimated time during the booking process.', 12, TRUE, TRUE, TRUE WHERE NOT EXISTS (SELECT 1 FROM public.public_faqs f WHERE f.faq_group='GENERAL' AND f.section_key='general' AND f.question='How Long Will The Car Service Take?');
